const esc = (value) => String(value).replace(/'/g, `''`);
const sqlText = (value) => (value == null || value === '' ? 'NULL' : `'${esc(value)}'`);
const sqlInt = (value) => {
  if (value == null || value === '') return 'NULL';
  const parsed = parseInt(value, 10);
  return Number.isNaN(parsed) ? 'NULL' : String(parsed);
};
const sqlDate = (value) => (value == null || value === '' ? 'NULL' : `'${esc(value)}'::date`);
const sqlBool = (value) => (value === false ? 'false' : 'true');
const assertUuid = (value, field) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)) {
    throw new Error(`Invalid ${field}: ${value}`);
  }
  return text;
};
const sqlUuid = (value, field) => (value ? `'${esc(assertUuid(value, field))}'` : 'NULL');
const makeUuid = () => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
    const rand = (Math.random() * 16) | 0;
    const value = char === 'x' ? rand : (rand & 0x3) | 0x8;
    return value.toString(16);
  });
};

const input = $input.first().json;
const query = input.query ?? input;

const search = String(query.search ?? '').trim();
const limit = Math.min(Math.max(parseInt(query.limit ?? '100', 10) || 100, 1), 500);
const page = Math.max(parseInt(query.page ?? '1', 10) || 1, 1);

return [{ json: {
  search_sql: search ? `'%${esc(search)}%'` : 'NULL',
  limit,
  offset: (page - 1) * limit,
} }];

