const usable = items.filter((item) => String(item?.medicamento_texto ?? '').trim());
if (usable.length === 0) throw new Error('at least one medication is required');

const id = body.id ? assertUuid(body.id, 'id') : makeUuid();
const fecha = String(body.fecha).split('T')[0];

// Una fila VALUES por ítem. El orden de las columnas debe coincidir con el
// INSERT de "RX Upsert — Save".
const itemsValues = usable.map((item, index) => [
  `'${esc(id)}'::uuid`,
  String(index),
  sqlInt(item.medicamento_id),
  sqlText(String(item.medicamento_texto).trim()),
  sqlText(item.presentacion),
  sqlText(item.dosis),
  sqlText(item.via_administracion),
  sqlText(item.frecuencia),
  sqlInt(item.duracion_dias),
  sqlText(item.cantidad),
  sqlDate(item.fecha_inicio ? String(item.fecha_inicio).split('T')[0] : fecha),
  sqlDate(item.fecha_fin ? String(item.fecha_fin).split('T')[0] : null),
  sqlText(item.indicaciones),
  sqlBool(item.registrar_en_anamnesis),
].join(', ')).map((row) => `(${row})`).join(',\n  ');

return [{ json: {
  id,
  id_sql: `'${esc(id)}'::uuid`,
  patient_id_sql: `'${esc(patientId)}'::uuid`,
  doctor_id_sql: `'${esc(doctorId)}'::uuid`,
  doctor_name_sql: sqlText(body.doctor_name),
  fecha_sql: `'${esc(fecha)}'::date`,
  template_id_sql: sqlUuid(body.template_id, 'template_id'),
  template_name_sql: sqlText(body.template_name),
  diagnostico_sql: sqlText(body.diagnostico),
  notas_sql: sqlText(body.notas),
  content_html_sql: sqlText(contentHtml),
  items_values_sql: itemsValues,
} }];

